flowchart TB
  subgraph USE1["us-east-1（バージニア北部）"]
    P@{ svc: "AWS CodePipeline", label: "パイプライン（AWS CLI で管理）" }
    SRC@{ svc: "Amazon S3", label: "ソースのバケット" }
    B1@{ svc: "Amazon S3", label: "アーティファクトバケット（us-east-1）" }
  end
  subgraph APNE1["ap-northeast-1（東京）"]
    B2@{ svc: "Amazon S3", label: "✔ C: アーティファクトバケット（東京）を作って登録" }
    CF@{ svc: "AWS CloudFormation", label: "スタックをデプロイするアクション" }
  end
  P --- B1
  P -- "東京へのデプロイを追加" --> CF
  B2 == "✔ C: 東京のアクションの成果物の置き場" ==> CF
  SRC -. "⚠ A: ソース用・別リージョンのバケットは使えない" .-> CF
  B1 -. "⚠ B: リージョン間のコピーを足す（要件に反する）" .-> B2
